 	private EclipseNode generateBuilderAbstractClass(BuilderJob job, TypeReference superclassBuilderClass, String classGenericName, String builderGenericName) {
 		TypeDeclaration parent = (TypeDeclaration) job.parentType.get();
 		TypeDeclaration builder = new TypeDeclaration(parent.compilationResult);
 		builder.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
 		builder.modifiers |= ClassFileConstants.AccPublic | ClassFileConstants.AccStatic | ClassFileConstants.AccAbstract;
 		builder.name = job.builderClassNameArr;

 		// Keep any type params of the annotated class.
 		builder.typeParameters = Arrays.copyOf(copyTypeParams(job.typeParams, job.source), job.typeParams.length + 2);
 		// Add builder-specific type params required for inheritable builders.
 		// 1. The return type for the build() method, named "C", which extends the annotated class.
 		TypeParameter o = new TypeParameter();
 		o.name = classGenericName.toCharArray();
 		o.type = cloneSelfType(job.parentType, job.source);
 		builder.typeParameters[builder.typeParameters.length - 2] = o;
 		// 2. The return type for all setter methods, named "B", which extends this builder class.
 		o = new TypeParameter();
 		o.name = builderGenericName.toCharArray();
 		TypeReference[] typerefs = appendBuilderTypeReferences(job.typeParams, classGenericName, builderGenericName);
 		o.type = generateParameterizedTypeReference(job.parentType, job.builderClassNameArr, false, typerefs, 0);
 		builder.typeParameters[builder.typeParameters.length - 1] = o;

 		if (superclassBuilderClass != null) builder.superclass = copyType(superclassBuilderClass, job.source);

 		builder.createDefaultConstructor(false, true);

 		builder.traverse(new SetGeneratedByVisitor(job.source), (ClassScope) null);
 		return injectType(job.parentType, builder);
 	}

 	private EclipseNode generateBuilderImplClass(BuilderJob job, String builderImplClass) {
 		TypeDeclaration parent = (TypeDeclaration) job.parentType.get();
 		TypeDeclaration builder = new TypeDeclaration(parent.compilationResult);
 		builder.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
 		builder.modifiers |= ClassFileConstants.AccPublic | ClassFileConstants.AccStatic | ClassFileConstants.AccFinal;
 		builder.name = (job.builderClassName + builderImplClass).toCharArray();

 		// Extend the abstract builder.
 		TypeReference extending = namePlusTypeParamsToTypeReference(job.parentType, job.builderClassNameArr, false, job.typeParams, 0);
 		TypeReference[] typeParamsForBuilder = appendBuilderTypeReferences(job.typeParams, "C", "B");
 		builder.superclass = generateParameterizedTypeReference(job.parentType, job.builderClassNameArr, false, typeParamsForBuilder, 0);

 		builder.createDefaultConstructor(false, true);

 		builder.traverse(new SetGeneratedByVisitor(job.source), (ClassScope) null);
 		return injectType(job.parentType, builder);
 	}

 	private void generateBuilderBasedConstructor(SuperBuilderJob job, boolean callBuilderBasedSuperConstructor) {
 		TypeDeclaration parent = (TypeDeclaration) job.parentType.get();
 		TypeDeclaration builder = (TypeDeclaration) job.builderImplType.get();

 		ConstructorDeclaration constructor = new ConstructorDeclaration(builder.compilationResult);
 		constructor.modifiers = ClassFileConstants.AccProtected;
 		constructor.traverse(new SetGeneratedByVisitor(job.source), builder.scope);

 		List<Statement> statements = new ArrayList<Statement>();
 		Argument builderArg = new Argument(BUILDER_VARIABLE_NAME, 0, namePlusTypeParamsToTypeReference(job.parentType, job.builderClassNameArr, false, job.typeParams, 0), Modifier.FINAL);
 		constructor.arguments = new Argument[] {builderArg};

 		for (BuilderFieldData bfd : job.builderFields) {
 			Expression rhs;
 			if (bfd.singularData != null && bfd.singularData.getSingularizer() != null) {
 				bfd.singularData.getSingularizer().appendBuildCode(bfd.singularData, bfd.originalFieldNode, job.sourceNode, statements, bfd.builderFieldName, BUILDER_VARIABLE_NAME_STRING);
 				rhs = new SingleNameReference(bfd.singularData.getPluralName(), 0);
 			} else {
 				rhs = new QualifiedNameReference(new char[][] {BUILDER_VARIABLE_NAME, bfd.builderFieldName}, new long[] {0, 0}, 0, 0);
 			}
 			Assignment assignment = new Assignment(new SingleNameReference(bfd.rawName, 0), rhs, 0);

 			// In case of @Builder.Default, set the value to the default if it was not set in the builder.
 			if (bfd.nameOfSetFlag != null) {
 				char[][] setVariableInBuilder = new char[][] {BUILDER_VARIABLE_NAME, bfd.nameOfSetFlag};
 				long[] positions = new long[] {0, 0};
 				QualifiedNameReference setVariableInBuilderRef = new QualifiedNameReference(setVariableInBuilder, positions, 0, 0);

 				MessageSend defaultMethodCall = new MessageSend();
 				defaultMethodCall.sourceStart = job.source.sourceStart;
 				defaultMethodCall.sourceEnd = job.source.sourceEnd;
 				defaultMethodCall.receiver = generateNameReference(job.parentType, 0L);
 				defaultMethodCall.selector = bfd.nameOfDefaultProvider;
 				defaultMethodCall.typeArguments = typeParameterNames(((TypeDeclaration) job.parentType.get()).typeParameters);

 				Statement defaultAssignment = new Assignment(new SingleNameReference(bfd.rawName, 0), defaultMethodCall, 0);
 				IfStatement ifBlockForDefault = new IfStatement(setVariableInBuilderRef, assignment, defaultAssignment, 0, 0);
 				statements.add(ifBlockForDefault);
 			} else {
 				statements.add(assignment);
 			}

 			if (hasNonNullAnnotations(bfd.originalFieldNode)) {
 				Statement nullCheck = generateNullCheck((FieldDeclaration) bfd.originalFieldNode.get(), job.sourceNode, null);
 				if (nullCheck != null) statements.add(nullCheck);
 			}
 		}

 		constructor.statements = statements.isEmpty() ? null : statements.toArray(new Statement[0]);
 		if (job.checkerFramework.generateSideEffectFree()) {
 			constructor.annotations = new Annotation[] {generateNamedAnnotation(job.source, CheckerFrameworkVersion.NAME__SIDE_EFFECT_FREE)};
 		}

 		constructor.traverse(new SetGeneratedByVisitor(job.source), builder.scope);

 		injectMethod(job.parentType, constructor);
 	}

+	private void generateAbstractBuilderMethods(SuperBuilderJob job, boolean addJavadoc) {
+		TypeDeclaration builder = (TypeDeclaration) job.builderAbstractType.get();
+		
+		// Generate setter methods for each field.
+		for (BuilderFieldData bfd : job.builderFields) {
+			MethodDeclaration method = generateSetterMethod(job, bfd, addJavadoc);
+			if (method != null) {
+				method.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+				builder.methods = addMethod(builder.methods, method);
+			}
+		}
+		
+		// Generate the abstract self() method.
+		MethodDeclaration selfMethod = generateAbstractSelfMethod(job);
+		selfMethod.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+		builder.methods = addMethod(builder.methods, selfMethod);
+		
+		// Generate the abstract build() method.
+		MethodDeclaration buildMethod = generateAbstractBuildMethod(job);
+		buildMethod.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+		builder.methods = addMethod(builder.methods, buildMethod);
+		
+		// Generate the toString() method.
+		MethodDeclaration toStringMethod = generateBuilderToStringMethod(job);
+		toStringMethod.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+		builder.methods = addMethod(builder.methods, toStringMethod);
+	}
