+	private void generateBuilderImplMethods(SuperBuilderJob job, boolean addJavadoc) {
+		TypeDeclaration builder = (TypeDeclaration) job.builderImplType.get();
+		
+		// Generate the self() method.
+		MethodDeclaration selfMethod = generateSelfMethod(job);
+		selfMethod.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+		builder.methods = addMethod(builder.methods, selfMethod);
+		
+		// Generate the build() method.
+		MethodDeclaration buildMethod = generateBuildMethod(job, null);
+		buildMethod.traverse(new SetGeneratedByVisitor(job.source), builder.scope);
+		builder.methods = addMethod(builder.methods, buildMethod);
+	}
+
+	private MethodDeclaration generateSetterMethod(SuperBuilderJob job, BuilderFieldData bfd, boolean addJavadoc) {
+		TypeDeclaration builder = (TypeDeclaration) job.builderAbstractType.get();
+		MethodDeclaration out = job.createNewMethodDeclaration();
+		out.selector = bfd.builderFieldName;
+		out.modifiers = ClassFileConstants.AccPublic;
+		out.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
+		
+		// Add type params if there are any.
+		if (job.typeParams != null && job.typeParams.length > 0) out.typeParameters = copyTypeParams(job.typeParams, job.source);
+		
+		// Return type is the builder type.
+		out.returnType = new SingleTypeReference(job.builderAbstractClassNameArr, 0);
+		
+		// Argument.
+		TypeReference argType = bfd.type;
+		Argument arg = new Argument(bfd.builderFieldName, 0, argType, Modifier.FINAL);
+		out.arguments = new Argument[] {arg};
+		
+		// Body.
+		List<Statement> statements = new ArrayList<Statement>();
+		
+		// this.fieldName = arg;
+		Assignment assignment = new Assignment(new SingleNameReference(bfd.builderFieldName, 0), new SingleNameReference(bfd.builderFieldName, 0), 0);
+		statements.add(assignment);
+		
+		// If @Singular, add singular logic.
+		if (bfd.singularData != null && bfd.singularData.getSingularizer() != null) {
+			bfd.singularData.getSingularizer().appendBuildCode(bfd.singularData, bfd.originalFieldNode, job.sourceNode, statements, bfd.builderFieldName, BUILDER_VARIABLE_NAME_STRING);
+		}
+		
+		// return self();
+		MessageSend selfCall = new MessageSend();
+		selfCall.receiver = ThisReference.implicitThis();
+		selfCall.selector = SELF_METHOD_NAME;
+		Statement returnStatement = new ReturnStatement(selfCall, 0, 0);
+		statements.add(returnStatement);
+		
+		out.statements = statements.isEmpty() ? null : statements.toArray(new Statement[0]);
+		
+		// Add Javadoc if requested.
+		if (addJavadoc) {
+			out.javadoc = JAVADOC_TAG;
+		}
+		
+		if (job.checkerFramework.generateUnique()) {
+			int len = out.returnType.getTypeName().length;
+			out.returnType.annotations = new Annotation[len][];
+			out.returnType.annotations[len - 1] = new Annotation[] {generateNamedAnnotation(job.source, CheckerFrameworkVersion.NAME__UNIQUE)};
+		}
+		
+		createRelevantNonNullAnnotation(job.parentType, out);
+		return out;
+	}
+
+	private MethodDeclaration generateAbstractSelfMethod(SuperBuilderJob job) {
+		TypeDeclaration builder = (TypeDeclaration) job.builderAbstractType.get();
+		MethodDeclaration out = job.createNewMethodDeclaration();
+		out.selector = SELF_METHOD_NAME;
+		out.modifiers = ClassFileConstants.AccProtected | ClassFileConstants.AccAbstract;
+		out.bits |= Eclipse.ECLIPSE_DO_NOT_TOUCH_FLAG;
+		
+		// Return type is the builder type.
+		out.returnType = new SingleTypeReference(job.builderAbstractClassNameArr, 0);
+		
+		if (job.checkerFramework.generateSideEffectFree()) {
+			out.annotations = new Annotation[] {generateNamedAnnotation(job.source, CheckerFrameworkVersion.NAME__SIDE_EFFECT_FREE)};
+		}
